<?php
require_once __DIR__ . '/../includes/bootstrap.php';require_role('supervisor');require_once __DIR__ . '/_helpers.php';
$user=current_user();$flashes=render_flashes();$currentPage='candidate_view';$pageTitle='Candidate Details';$supervisorId=(int)($user['id']??$user['user_id']??0);$candidateId=(int)($_GET['id']??0);$cohortId=(int)($_GET['cohort_id']??0);if($supervisorId<=0||$candidateId<=0){http_response_code(400);exit('Invalid request.');}
$sql="SELECT u.id candidate_id,u.first_name,u.last_name,u.email,cp.id participation_id,cp.status participant_status,cp.selected_at,cp.onboarded_at,cp.completed_at,c.id cohort_id,c.name cohort_name,c.start_date,c.end_date,p.name programme_name,p.type programme_type FROM cohort_participants cp JOIN cohorts c ON c.id=cp.cohort_id JOIN programmes p ON p.id=c.programme_id JOIN users u ON u.id=cp.user_id WHERE u.id=? AND c.supervisor_id=?";$types='ii';$params=[$candidateId,$supervisorId];if($cohortId>0){$sql.=' AND c.id=?';$types.='i';$params[]=$cohortId;}$sql.=' ORDER BY cp.id DESC LIMIT 1';$stmt=Database::prepare($sql,$types,$params);$candidate=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$candidate){http_response_code(404);exit('Candidate not found in your assigned cohorts.');}
$fn=trim((string)$candidate['first_name']);$ln=trim((string)$candidate['last_name']);$name=trim($fn.' '.$ln)?:'Candidate';
require __DIR__ . '/_layout_start.php';
?>
