<div class="sv-grid sv-grid--2"><section class="sv-card"><div class="sv-card__header"><div><h3>Candidate Profile</h3><p>Basic candidate information.</p></div></div><div class="sv-card__body"><div class="sv-person" style="margin-bottom:18px"><div class="sv-avatar" style="width:56px;height:56px;flex-basis:56px;font-size:14px"><?= e(sv_initials($fn,$ln)) ?></div><div class="sv-person__copy"><strong style="font-size:14px"><?= e($name) ?></strong><span><?= e((string)$candidate['email']) ?></span></div></div><p><strong>Programme:</strong> <?= e($candidate['programme_name']) ?></p><p><strong>Programme type:</strong> <?= e((string)$candidate['programme_type']) ?></p><p><strong>Cohort:</strong> <?= e($candidate['cohort_name']) ?></p><p><strong>Status:</strong> <span class="sv-status sv-status--<?= e(sv_status_class($candidate['participant_status'])) ?>"><?= e(sv_status_label($candidate['participant_status'])) ?></span></p></div></section><section class="sv-card"><div class="sv-card__header"><div><h3>Participation Timeline</h3><p>Recorded cohort milestones.</p></div></div><div class="sv-card__body"><p><strong>Selected:</strong> <?= e(sv_datetime($candidate['selected_at'])) ?></p><p><strong>Onboarded:</strong> <?= e(sv_datetime($candidate['onboarded_at'])) ?></p><p><strong>Completed:</strong> <?= e(sv_datetime($candidate['completed_at'])) ?></p><p><strong>Cohort period:</strong> <?= e(sv_date($candidate['start_date'])) ?> — <?= e(sv_date($candidate['end_date'])) ?></p></div></section></div>
<div class="sv-security"><i class="fas fa-shield-halved"></i><div><strong>Protected candidate record</strong><p>This page validates the candidate through a cohort assigned to your Supervisor account before displaying any information.</p></div></div>
